/**
 * @file main.c
 * @brief M2 Controller main application
 *
 * NOTE: This is application-level code. STM32 HAL initialization
 * (MX_GPIO_Init, MX_USART3_UART_Init, MX_I2C1_Init, MX_TIM6_Init, etc.)
 * is generated by STM32CubeMX and not shown here. This file provides
 * the main loop, UART RX handling, and task wiring.
 *
 * To use: Generate the full project via STM32CubeMX (see README.md),
 * then merge this main.c application logic into the generated main.c.
 */

#include "main.h"

UART_HandleTypeDef huart3;
I2C_HandleTypeDef hi2c1;
TIM_HandleTypeDef htim6;
TIM_HandleTypeDef htim7;

/* UART RX buffer (line-based parsing) */
#define RX_BUF_SIZE SERIAL_JSON_MAX_LINE
static char g_rx_buffer[RX_BUF_SIZE];
static uint16_t g_rx_index = 0;
static uint8_t g_rx_byte;

/* serial_json_tx implementation (called from serial_json.c) */
void serial_json_tx(const char *data, uint16_t len) {
    HAL_UART_Transmit(&huart3, (uint8_t *)data, len, 100);
}

static void process_rx_line(char *line) {
    parsed_message_t msg;
    if (!serial_json_parse(line, &msg)) return;

    if (msg.type == MSG_TYPE_COMMAND) {
        if (strcmp(msg.command, "interlock_release") == 0) {
            controller_handle_release_request(&msg.grant);
        } else if (strcmp(msg.command, "interlock_assert") == 0) {
            controller_assert_isolated();
        }
    } else if (msg.type == MSG_TYPE_TIME_SYNC) {
        /* FW-004: M1 wall-clock sync — expiry validation fails closed until
         * at least one valid time_sync frame arrives. */
        if (msg.time_valid) {
            controller_update_time(msg.time_epoch_s);
        }
    }
}

static void uart_rx_byte_handler(uint8_t byte) {
    if (byte == '\n' || byte == '\r') {
        if (g_rx_index > 0) {
            g_rx_buffer[g_rx_index] = '\0';
            process_rx_line(g_rx_buffer);
            g_rx_index = 0;
        }
    } else {
        if (g_rx_index < RX_BUF_SIZE - 1) {
            g_rx_buffer[g_rx_index++] = (char)byte;
        }
    }
}

/* HAL_UART_RxCpltCallback (called by HAL when byte received) */
void HAL_UART_RxCpltCallback(UART_HandleTypeDef *huart) {
    if (huart == &huart3) {
        uart_rx_byte_handler(g_rx_byte);
        HAL_UART_Receive_IT(&huart3, &g_rx_byte, 1);
    }
}

/* FW-009 (audit 2026-08): ISR-context work is deferred to the main loop via
 * pending flags. The previous callbacks called controller_handle_estop() /
 * controller_send_heartbeat() directly, which drive HAL_UART_Transmit with a
 * 100 ms timeout INSIDE interrupt context — a reentrancy/robustness hazard
 * (blocking ISR, potential HAL state corruption when an RX complete fires
 * mid-transmit). ISRs now only set volatile flags; all serial I/O happens in
 * thread mode. */
static volatile bool g_estop_pending = false;
static volatile bool g_heartbeat_due = false;

/* Heartbeat timer callback (TIM6, every 5s) */
void HAL_TIM_PeriodElapsedCallback(TIM_HandleTypeDef *htim) {
    if (htim == &htim6) {
        g_heartbeat_due = true;
    }
    if (htim == &htim7) {
        g_estop_pending = true; /* sampled e-stop poll timer */
    }
}

/* EXTI callback (E-stop button PC13) */
void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin) {
    if (GPIO_Pin == ESTOP_BUTTON_PIN) {
        g_estop_pending = true;
    }
}

void Error_Handler(void) {
    interlock_drive_relay(false);
    interlock_set_light(1, 0, 0, 1);
    while (1) { }
}

void controller_main_loop(void) {
    controller_init();
    serial_json_init();
    serial_json_send_hello();
    HAL_UART_Receive_IT(&huart3, &g_rx_byte, 1);
    HAL_TIM_Base_Start_IT(&htim6);
    HAL_TIM_Base_Start_IT(&htim7);

    uint32_t last_report = 0;
    while (1) {
        uint32_t now = HAL_GetTick();
        if (now - last_report >= 10000) {
            controller_send_state_report();
            last_report = now;
        }
        /* FW-009: drain ISR-pending work in thread mode. The e-stop handler
         * also runs directly when the pin still reads pressed (belt and
         * braces: the physical NC circuit already breaks the relay). */
        if (g_heartbeat_due) {
            g_heartbeat_due = false;
            controller_send_heartbeat();
        }
        if (g_estop_pending || interlock_read_estop()) {
            g_estop_pending = false;
            controller_handle_estop();
        }
    }
}
